\set ON_ERROR_STOP on
BEGIN;
SET LOCAL lock_timeout = '3s';
WITH u AS (UPDATE capability_evidence SET expires = recorded WHERE id IN ('ev_05e24f2180e1da5458592778cc0560da','ev_1509981e137fd41d3030970a64b6716c','ev_1d1b7519be3138dcaf2f79f38b432661','ev_2a6ac2911b237e1a2ba1ad8b9c555a3f','ev_3a4b623455ff95730dc9be8d418191e5','ev_3c7d77c0b4813a6719166028767a2c9d','ev_43c65b84315dd16c423b6b71127b8bbe','ev_5a3f6404a6c9e462333085c6f4ef431f','ev_6ccbb23be40e974e0f6bad90e1e78369','ev_7244e7ce939f4cd713268f9d29ea509a','ev_87225877191be9829fbd20df89579e36','ev_8782eb8e2dc6ca3875ea90b8db8f146f','ev_9139392ec4842cc4a698c00adf4f43b0','ev_9390bee32edd5308e9e3e5f14be57df3','ev_95494ae1bb384b7ac280662eed20256a','ev_95617d2423ae1df49e99c863d5ff06d0','ev_a115dad21b1f5e9b5eac2cc4ff4a2f3b','ev_a4425082fb99b6eeca4a2ec6ec683a6e','ev_a510b26e1a225f603353a6dc6d36f2a6','ev_af6694b7784244cd3f37cb4597c7f5ec','ev_bcd7bda0a42c0ba1b1014fff5559e9f8','ev_c8e0a3e7a74bcd3cfae309d59a47d856','ev_c97eb073c1378cbcbe197f87b5968a47','ev_cdf92e07d78dd0a677581f4ca90e980f','ev_cec431a53a4afd65dc6b7d6aabf8f18a','ev_d8931ed69eb3229b7f713a7adb8a3f05','ev_e91526954b01551c78d7f91894f0cbde','ev_ead6eabeeb4070878c7879ad67a4320c','ev_ec46002195d8025d5f3b4b3cc58b3c26','ev_f6956273bf597412c2c0cba60afe58fc') AND scope='execution' AND expires > recorded RETURNING 1)
SELECT count(*) AS ev_n FROM u \gset
WITH d AS (DELETE FROM capability_eligibility WHERE resource_id IN (34798,44690,51275,51727,53273,57426,124304,127473,144216,152539,156989,161088,186110,226660,241367,241415,254416,273451,281817,288041,298704,313829,401452,401454,401508,401520,401533,401549) AND executed_at BETWEEN 1794418304 AND 1794418544 RETURNING 1)
SELECT count(*) AS el_n FROM d \gset
\echo 근거 :ev_n / 자격 :el_n
SELECT (:ev_n = 30 AND :el_n = 25) AS ok \gset
\if :ok
COMMIT;
\echo COMMIT 완료
\else
ROLLBACK;
\echo ROLLBACK
\endif
